<script setup lang="ts">
import { Head } from '@inertiajs/vue3';
import { CalendarDays, ChevronLeft, ChevronRight, Clock3, RefreshCw, Users, UserRoundPlus } from 'lucide-vue-next';
import { computed, onMounted, ref } from 'vue';
import { toast } from 'vue-sonner';
import api from '@/utils/api';

defineOptions({ layout: { breadcrumbs: [{ title: 'Reservations', href: '/reservations' }] } });
type Reservation={id:number;contact_name:string;phone?:string|null;social_media?:string|null;reserved_at:string;party_size:number;status:string;notes?:string|null};
const rows=ref<Reservation[]>([]),month=ref(new Date()),selected=ref(new Date().toISOString().slice(0,10)),busy=ref(false),saving=ref(false);
const form=ref({contact_name:'',phone:'',social_media:'',reserved_at:'',party_size:1,status:'confirmed',notes:''});
const key=(d:Date)=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const active=(x:Reservation)=>!['cancelled','no_show'].includes(x.status);
const days=computed(()=>{const y=month.value.getFullYear(),m=month.value.getMonth(),first=new Date(y,m,1),out:any[]=[];for(let i=0;i<first.getDay();i++)out.push(null);for(let d=1;d<=new Date(y,m+1,0).getDate();d++){const date=new Date(y,m,d),k=key(date),bookings=rows.value.filter(x=>String(x.reserved_at).slice(0,10)===k&&active(x));out.push({d,k,count:bookings.length,guests:bookings.reduce((n,x)=>n+(Number(x.party_size)||0),0)})}return out});
const selectedRows=computed(()=>rows.value.filter(x=>String(x.reserved_at).slice(0,10)===selected.value).sort((a,b)=>a.reserved_at.localeCompare(b.reserved_at)));
const total=computed(()=>rows.value.filter(active).length),guests=computed(()=>rows.value.filter(active).reduce((n,x)=>n+(Number(x.party_size)||0),0)),confirmed=computed(()=>rows.value.filter(x=>x.status==='confirmed').length);
const selectedLabel=computed(()=>new Date(selected.value+'T00:00:00').toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric'}));
async function load(){busy.value=true;try{const y=month.value.getFullYear(),m=month.value.getMonth();rows.value=(await api.get('/api/v1/reservations',{params:{from:key(new Date(y,m,1))+' 00:00:00',to:key(new Date(y,m+1,0))+' 23:59:59'}})).data}catch{toast.error('Could not load reservations.')}finally{busy.value=false}}
function move(n:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1);load()}
function today(){month.value=new Date();selected.value=key(new Date());load()}
function choose(k:string){selected.value=k;if(!form.value.reserved_at)form.value.reserved_at=k+'T18:00'}
async function save(){if(!form.value.contact_name||!form.value.reserved_at){toast.error('Contact name and reservation time are required.');return}saving.value=true;try{await api.post('/api/v1/reservations',form.value);toast.success('Reservation saved.');form.value={contact_name:'',phone:'',social_media:'',reserved_at:'',party_size:1,status:'confirmed',notes:''};await load()}catch{toast.error('Could not save reservation.')}finally{saving.value=false}}
async function status(x:Reservation,s:string){try{await api.patch('/api/v1/reservations/'+x.id,{status:s});await load()}catch{toast.error('Could not update reservation.')}}
async function del(x:Reservation){if(!confirm('Delete this reservation?'))return;try{await api.delete('/api/v1/reservations/'+x.id);toast.success('Reservation deleted.');await load()}catch{toast.error('Could not delete reservation.')}}
onMounted(load);
</script>

<template>
<Head title="Reservations"/>
<div class="reservation-dashboard">
<header class="dashboard-heading"><div><p class="eyebrow"><CalendarDays :size="14"/> BYPASS GRILL / RESERVATIONS</p><h1>Plan the <em>next table.</em></h1><p class="intro">Plot bookings, keep customer details close, and see the month at a glance.</p></div><div class="heading-meta"><span>{{month.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}}</span><button class="refresh-button" :disabled="busy" @click="load"><RefreshCw :size="14" :class="{spinning:busy}"/>{{busy?'Refreshing…':'Refresh calendar'}}</button></div></header>
<section class="work-bar"><div class="work-bar-copy"><strong>Know who's coming before service starts.</strong><span>Select a day to inspect bookings or prefill a new reservation for that date.</span></div><button class="primary-action" @click="today"><CalendarDays :size="17"/>Today</button></section>
<section class="metric-grid"><article class="metric metric-featured"><p>Active reservations</p><strong>{{total}}</strong><span>Current month</span></article><article class="metric"><p>Expected guests</p><strong>{{guests}}</strong><span>Across active bookings</span></article><article class="metric"><p>Confirmed</p><strong>{{confirmed}}</strong><span>Ready for service</span></article><article class="metric"><p>Selected day</p><strong>{{selectedRows.filter(active).length}}</strong><span>{{selectedLabel}}</span></article></section>
<div class="dashboard-columns"><section class="panel calendar-panel"><div class="panel-heading"><div><p class="eyebrow">BOOKING CALENDAR</p><h2>{{month.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}}</h2></div><div class="month-actions"><button @click="move(-1)" aria-label="Previous month"><ChevronLeft :size="17"/></button><button @click="today">Today</button><button @click="move(1)" aria-label="Next month"><ChevronRight :size="17"/></button></div></div><div class="week"><b v-for="d in ['SUN','MON','TUE','WED','THU','FRI','SAT']" :key="d">{{d}}</b></div><div class="calendar"><button v-for="(d,i) in days" :key="i" class="day" :class="{blank:!d,selected:d&&selected===d.k,booked:d&&d.count}" :disabled="!d" @click="d&&choose(d.k)"><template v-if="d"><span class="date">{{d.d}}</span><span v-if="d.count" class="booking-count">{{d.count}} booking{{d.count>1?'s':''}}</span><small v-if="d.guests">{{d.guests}} guest{{d.guests>1?'s':''}}</small><i v-if="d.count"></i></template></button></div></section>
<aside class="panel form-panel"><div class="form-icon"><UserRoundPlus :size="20"/></div><p class="eyebrow">NEW RESERVATION</p><h2>Save a booking.</h2><p class="panel-copy">Customer contact details stay attached to the reservation for quick follow-up.</p><label>Contact name<input v-model="form.contact_name" placeholder="Customer name"></label><div class="field-pair"><label>Phone<input v-model="form.phone" placeholder="09xx xxx xxxx"></label><label>Party size<input v-model.number="form.party_size" type="number" min="1"></label></div><label>Social media<input v-model="form.social_media" placeholder="@username or profile"></label><label>Date & time<input v-model="form.reserved_at" type="datetime-local"></label><label>Notes<textarea v-model="form.notes" rows="3" placeholder="Requests, occasion, seating notes…"></textarea></label><button class="save-action" :disabled="saving" @click="save">{{saving?'Saving…':'Save reservation'}}<ChevronRight :size="16"/></button></aside></div>
<section class="panel bookings-panel"><div class="panel-heading"><div><p class="eyebrow">SELECTED DAY</p><h2>{{selectedLabel}} <span class="count-badge">{{selectedRows.length}} bookings</span></h2></div><Clock3 :size="20" class="muted-icon"/></div><div v-if="selectedRows.length" class="booking-list"><article v-for="x in selectedRows" :key="x.id" class="booking-row"><div class="time-block"><strong>{{new Date(x.reserved_at).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'})}}</strong><span>{{x.party_size}} guest{{x.party_size>1?'s':''}}</span></div><div class="guest"><strong>{{x.contact_name}}</strong><span>{{x.phone||'No phone'}} · {{x.social_media||'No social media'}}</span><small v-if="x.notes">{{x.notes}}</small></div><div class="booking-actions"><select :value="x.status" :class="'status status-'+x.status" @change="status(x,($event.target as HTMLSelectElement).value)"><option v-for="s in ['pending','confirmed','arrived','completed','cancelled','no_show']" :key="s" :value="s">{{s.replace('_',' ')}}</option></select><button class="delete-action" @click="del(x)">Delete</button></div></article></div><div v-else class="empty-state"><Users :size="28"/><h3>No reservations yet.</h3><p>Select this date in the calendar and add the first booking.</p></div></section>
<footer class="dashboard-footer"><span>BYPASS GRILL · RESERVATION CONTROL</span><span>Calendar and customer booking workspace</span></footer>
</div>
</template>

<style scoped>
