fcf6;border:1px solid #ded7cb;border-radius:6px;padding:23px}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.panel h2{font-size:18px;font-weight:800;letter-spacing:-.5px}.month-actions{display:flex;gap:6px}.week,.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.week b{text-align:center;padding:9px 3px;font-size:8px;letter-spacing:1px;color:#777268}.day{position:relative;min-height:105px;border:1px solid #ece5da;background:#fffdf8;padding:10px;text-align:left;transition:transform .15s,border-color .15s,background .15s}.day:not(.blank):hover{z-index:1;transform:translateY(-2px);border-color:#c3441c;background:#fff9f2}.day.blank{background:#f7f3eb;cursor:default}.day.selected{z-index:2;outline:2px solid #ad3b19;outline-offset:-2px;background:#f8eee4}.day .date{font-size:12px;font-weight:800}.booking-count{display:block;margin-top:14px;font-size:10px;font-weight:800;color:#ad3b19}.day small{display:block;margin-top:3px;font-size:9px;color:#777268}.day i{position:absolute;right:9px;top:9px;width:6px;height:6px;border-radius:50%;background:#c3441c}.form-panel{align-self:start;background:#ebe8d3;border-color:#d8d3b8}.form-icon{display:grid;place-items:center;width:42px;height:42px;border:1px solid #bbb793;border-radius:50%;margin-bottom:17px}.form-panel h2{margin:8px 0}.form-panel label{display:flex;flex-direction:column;gap:6px;margin-top:12px;font-size:9px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#69644e}.form-panel input,.form-panel textarea,.booking-actions select{width:100%;border:1px solid #d4cdbf;border-radius:4px;background:#fffcf6;padding:11px;color:#24231e;font-size:12px;text-transform:none;letter-spacing:0}.field-pair{display:grid;grid-template-columns:1fr 90px;gap:9px}.save-action{width:100%;margin-top:16px}.save-action:disabled{opacity:.6}.bookings-panel{margin-top:22px}.count-badge{display:inline-block;margin-left:8px;padding:4px 8px;border-radius:20px;background:#f2e5d8;color:#ad3b19;font-size:10px;letter-spacing:0}.booking-row{display:grid;grid-template-columns:125px minmax(0,1fr) auto;align-items:center;gap:18px;padding:16px 0;border-top:1px solid #ece5da}.time-block strong,.guest strong{display:block;font-size:13px}.time-block span,.guest span,.guest small{display:block;margin-top:4px;font-size:10px;color:#777268}.guest small{color:#948d7e}.booking-actions{display:flex;align-items:center;gap:8px}.booking-actions select{width:125px;padding:8px;font-size:10px;font-weight:700}.delete-action{font-size:10px;font-weight:700;color:#a03015;padding:8px}.empty-state{display:flex;flex-direction:column;align-items:center;text-align:center;gap:9px;padding:32px;color:#777268}.empty-state svg{color:#ad3b19}.empty-state h3{font-size:15px;color:#24231e}.empty-state p{font-size:11px}.dashboard-footer{display:flex;justify-content:space-between;gap:15px;margin-top:30px;padding-top:18px;border-top:1px solid #ded7cb;font-size:9px;color:#777268}.spinning{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.reservation-dashboard :focus-visible{outline:2px solid #ad3b19;outline-offset:3px}
@media(max-width:1000px){.dashboard-columns{grid-template-columns:1fr}.form-panel{width:100%}}@media(max-width:760px){.reservation-dashboard{padding:24px 16px}.dashboard-heading{flex-direction:column}.heading-meta{align-items:flex-start}.metric-grid{grid-template-columns:repeat(2,1fr)}.day{min-height:78px;padding:7px}.booking-count{font-size:8px;margin-top:10px}.day small{display:none}.booking-row{grid-template-columns:90px 1fr}.booking-actions{grid-column:1/-1;justify-content:flex-end}}@media(max-width:520px){.work-bar{align-items:flex-start;flex-direction:column;padding:20px}.primary-action{width:100%}.metric{padding:15px}.metric strong{font-size:24px}.calendar-panel{padding:14px}.panel-heading{align-items:flex-start}.month-actions button{padding:8px}.month-actions button:nth-child(2){display:none}.day{min-height:62px}.booking-count{font-size:0}.booking-count:after{content:'Booked';font-size:8px}.field-pair{grid-template-columns:1fr}.booking-row{grid-template-columns:1fr}.time-block{display:flex;justify-content:space-between}.booking-actions{grid-column:auto;justify-content:space-between}.dashboard-footer{flex-direction:column}}
